// High-performance authentic Bayer dither point cloud (10637 particles, 74459 bytes)
// Authentic ordered Bayer dither matrix capturing facial contours, hair, and pointing hand
export const NEURAL_FACE_PARTICLES_B64 = "";
export const NEURAL_FACE_PARTICLES_COUNT = 10637;

export type NeuralPoint = {
  nx: number; // 0..1 relative to original mesh width (1024)
  ny: number; // 0..1 relative to original mesh height (612)
  r: number;
  g: number;
  b: number;
  size: number;
};

export function decodeNeuralParticles(): NeuralPoint[] {
  if (typeof window === "undefined") return [];
  const binary = atob(NEURAL_FACE_PARTICLES_B64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  const dv = new DataView(bytes.buffer);
  const points: NeuralPoint[] = [];
  const stride = 7;
  const count = Math.floor(bytes.length / stride);

  for (let i = 0; i < count; i++) {
    const offset = i * stride;
    const nx = dv.getUint16(offset, true) / 10000;
    const ny = dv.getUint16(offset + 2, true) / 10000;
    const r = dv.getUint8(offset + 4);
    const g = dv.getUint8(offset + 5);
    const b = dv.getUint8(offset + 6);
    const lum = r * 0.299 + g * 0.587 + b * 0.114;
    // Authentic Bayer halftone dot sizing
    const size = lum < 120 ? 1.5 : lum < 180 ? 2.0 : 2.5;
    points.push({ nx, ny, r, g, b, size });
  }
  return points;
}
